// External 2026 forecasts, for /analysis/forecasts. Hand-maintained snapshot: each entry is one
// published forecast (a quantitative model or a qualitative race-rater) with its chamber toplines
// and per-race calls, as read from the forecaster's own site (or, for the raters, Wikipedia's
// aggregated rating tables, which cite each rater's page). Refresh by re-reading the sites and
// bumping `asOf`; nothing here feeds the model.
//
// Keys: Senate by state abbreviation, the Florida and Ohio specials as "FL-2" / "OH-2"; governors
// by state abbreviation; House by the "AL-01" district name (lib/forecastComparison externalKeyOf).

export type ExternalRating =
  | "Safe D" | "Likely D" | "Lean D" | "Tilt D" | "Toss-up" | "Tilt R" | "Lean R" | "Likely R" | "Safe R";

export interface ExternalRaceCall {
  rating?: ExternalRating;
  pDem?: number; // Democratic win probability, 0–1
}

export interface ExternalChamberTotal {
  pDemControl?: number; // probability Democrats control the chamber (models only)
  demSeats?: number;    // expected / median Democratic seats (models) or seats rated at least Tilt D (raters)
  repSeats?: number;
  tossups?: number;     // raters: seats rated Toss-up (demSeats + repSeats + tossups = chamber size)
  range80?: [number, number]; // 80% interval of Democratic seats, where published
}

export interface ExternalForecaster {
  id: string;
  name: string;
  /** Shorter label for the race-by-race column headings, where the full name will not fit. */
  shortName?: string;
  kind: "model" | "ratings";
  description: string;
  asOf: string; // YYYY-MM-DD of the snapshot read
  urls: { home: string; house?: string; senate?: string; governor?: string };
  totals: { house?: ExternalChamberTotal; senate?: ExternalChamberTotal; governor?: ExternalChamberTotal };
  races: { senate: Record<string, ExternalRaceCall>; governor: Record<string, ExternalRaceCall>; house: Record<string, ExternalRaceCall> };
  // Chambers where the forecaster publishes only its competitive races: every race it leaves out
  // is Safe for the party ahead there (the comparison fills those in, flagged as inferred).
  inferSafe?: ("house" | "senate" | "governor")[];
  notes?: string;
}

